<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <climits>
#include <string>
using namespace std;

int globalN, globalT;
vector<string> firstGrid, secondGrid;
int distFromZ[30][30], distToZ[30][30];
const int dirX[4] = {0, 0, -1, 1};
const int dirY[4] = {1, -1, 0, 0};

struct MyEdge {
    int from, to, cap, flow;
    MyEdge(int f, int t, int c) : from(f), to(t), cap(c), flow(0) {}
};

vector<MyEdge> edgeList;
vector<int> adjList[2005];
int levels[2005], currentPos[2005];

bool inBoard(int x, int y) {
    return x >= 0 && x < globalN && y >= 0 && y < globalN;
}

void firstBfs(int startX, int startY) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j)
            distFromZ[i][j] = INT_MAX;
    queue<pair<int, int>> q;
    q.push({startX, startY});
    distFromZ[startX][startY] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (inBoard(nx, ny) && distFromZ[nx][ny] == INT_MAX && secondGrid[nx][ny] != 'Y') {
                distFromZ[nx][ny] = distFromZ[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void secondBfs(int startX, int startY) {
    for (int i = 0; i < 30; ++i)
        for (int j = 0; j < 30; ++j)
            distToZ[i][j] = INT_MAX;
    queue<pair<int, int>> q;
    q.push({startX, startY});
    distToZ[startX][startY] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (distToZ[x][y] >= distFromZ[x][y]) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (inBoard(nx, ny) && distToZ[nx][ny] == INT_MAX && firstGrid[nx][ny] != 'Y' && distToZ[x][y] + 1 <= distFromZ[nx][ny]) {
                distToZ[nx][ny] = distToZ[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

bool buildLevelGraph() {
    memset(levels, -1, sizeof(levels));
    queue<int> q;
    q.push(0);
    levels[0] = 0;
    while (!q.empty() && levels[globalN * globalN * 2 + 1] == -1) {
        int u = q.front(); q.pop();
        for (int eid : adjList[u]) {
            auto &e = edgeList[eid];
            if (levels[e.to] == -1 && e.flow < e.cap) {
                levels[e.to] = levels[u] + 1;
                q.push(e.to);
            }
        }
    }
    return levels[globalN * globalN * 2 + 1] != -1;
}

int pushFlow(int node, int bottleneck) {
    if (!bottleneck || node == globalN * globalN * 2 + 1) return bottleneck;
    for (int &i = currentPos[node]; i < (int)adjList[node].size(); ++i) {
        int eid = adjList[node][i];
        auto &e = edgeList[eid];
        if (levels[e.to] != levels[node] + 1) continue;
        int sent = pushFlow(e.to, min(bottleneck, e.cap - e.flow));
        if (sent) {
            e.flow += sent;
            edgeList[eid ^ 1].flow -= sent;
            return sent;
        }
    }
    return 0;
}

int computeMaxFlow() {
    int total = 0;
    while (buildLevelGraph()) {
        memset(currentPos, 0, sizeof(currentPos));
        while (int sent = pushFlow(0, INT_MAX)) {
            total += sent;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> globalN >> globalT;
    firstGrid.resize(globalN);
    secondGrid.resize(globalN);
    for (int i = 0; i < globalN; ++i) cin >> firstGrid[i];
    for (int i = 0; i < globalN; ++i) cin >> secondGrid[i];

    int zx = -1, zy = -1;
    for (int i = 0; i < globalN; ++i) {
        for (int j = 0; j < globalN; ++j) {
            if (secondGrid[i][j] == 'Z') {
                firstGrid[i][j] = secondGrid[i][j] = 'Y';
                zx = i; zy = j;
            }
        }
    }

    firstBfs(zx, zy);

    int totalNodes = 2 * globalN * globalN + 2;
    for (int i = 0; i < totalNodes; ++i) adjList[i].clear();
    edgeList.clear();

    for (int i = 0; i < globalN; ++i) {
        for (int j = 0; j < globalN; ++j) {
            if (firstGrid[i][j] == 'Y') continue;
            int u = i * globalN + j + 1;
            int v = globalN * globalN + u;
            int val1 = firstGrid[i][j] - '0';
            int val2 = secondGrid[i][j] - '0';

            edgeList.emplace_back(0, u, val1);
            adjList[0].push_back(edgeList.size() - 1);
            edgeList.emplace_back(u, 0, 0);
            adjList[u].push_back(edgeList.size() - 1);

            edgeList.emplace_back(v, totalNodes - 1, val2);
            adjList[v].push_back(edgeList.size() - 1);
            edgeList.emplace_back(totalNodes - 1, v, 0);
            adjList[totalNodes - 1].push_back(edgeList.size() - 1);

            secondBfs(i, j);
            for (int x = 0; x < globalN; ++x) {
                for (int y = 0; y < globalN; ++y) {
                    if (secondGrid[x][y] == 'Y' || distToZ[x][y] > globalT) continue;
                    int w = globalN * globalN + x * globalN + y + 1;
                    edgeList.emplace_back(u, w, val1);
                    adjList[u].push_back(edgeList.size() - 1);
                    edgeList.emplace_back(w, u, 0);
                    adjList[w].push_back(edgeList.size() - 1);
                }
            }
        }
    }

    cout << computeMaxFlow() << '\n';
    return 0;
}
